const STAGES = [
  { key: 'pending', label: '待投递' },
  { key: 'applied', label: '已投递' },
  { key: 'interview', label: '面试中' },
  { key: 'closed', label: '已结束' }
];
const STAGE_LABEL = STAGES.reduce((acc, s) => { acc[s.key] = s.label; return acc; }, {});
const STAGE_KEYS = STAGES.map((s) => s.key);
const FILTER_ALL = 'all';

const el = {
  stats: document.querySelector('[data-role="stats"]'),
  statsTotal: document.querySelector('[data-role="stats-total"]'),
  form: document.querySelector('[data-role="form"]'),
  formTitle: document.querySelector('[data-role="form-title"]'),
  company: document.querySelector('[data-role="input-company"]'),
  position: document.querySelector('[data-role="input-position"]'),
  date: document.querySelector('[data-role="input-date"]'),
  stage: document.querySelector('[data-role="input-stage"]'),
  note: document.querySelector('[data-role="input-note"]'),
  formError: document.querySelector('[data-role="form-error"]'),
  submitBtn: document.querySelector('[data-role="submit-btn"]'),
  cancelBtn: document.querySelector('[data-role="cancel-btn"]'),
  filters: document.querySelector('[data-role="filters"]'),
  list: document.querySelector('[data-role="list"]'),
  listCount: document.querySelector('[data-role="list-count"]'),
  empty: document.querySelector('[data-role="empty"]'),
  dialogMask: document.querySelector('[data-role="dialog-mask"]'),
  dialogTitle: document.querySelector('[data-role="dialog-title"]'),
  dialogText: document.querySelector('[data-role="dialog-text"]'),
  dialogCancel: document.querySelector('[data-role="dialog-cancel"]'),
  dialogConfirm: document.querySelector('[data-role="dialog-confirm"]')
};

let state = null;
let activeFilter = FILTER_ALL;
let editingId = null;
let saving = false;

function normalizeStage(value) {
  return STAGE_KEYS.indexOf(value) >= 0 ? value : 'pending';
}

function normalizeRecord(raw) {
  const source = raw && typeof raw === 'object' ? raw : {};
  const record = Object.assign({}, source);
  record.id = typeof source.id === 'string' && source.id ? source.id : 'rec-' + Date.now() + '-' + Math.random().toString(36).slice(2, 8);
  record.company = typeof source.company === 'string' ? source.company : '';
  record.position = typeof source.position === 'string' ? source.position : '';
  record.applyDate = typeof source.applyDate === 'string' ? source.applyDate : '';
  record.stage = normalizeStage(source.stage);
  record.note = typeof source.note === 'string' ? source.note : '';
  return record;
}

function normalizeState(raw) {
  const source = raw && typeof raw === 'object' ? raw : {};
  const next = Object.assign({}, source);
  const records = Array.isArray(source.records) ? source.records : [];
  next.records = records.map(normalizeRecord);
  return next;
}

function getRecords() {
  return Array.isArray(state.records) ? state.records : [];
}

function countByStage(records) {
  const counts = {};
  STAGE_KEYS.forEach((key) => { counts[key] = 0; });
  records.forEach((r) => {
    const key = normalizeStage(r.stage);
    counts[key] += 1;
  });
  return counts;
}

function todayISO() {
  const d = new Date();
  const m = String(d.getMonth() + 1).padStart(2, '0');
  const day = String(d.getDate()).padStart(2, '0');
  return d.getFullYear() + '-' + m + '-' + day;
}

function renderStats() {
  const records = getRecords();
  const counts = countByStage(records);
  el.stats.textContent = '';
  STAGES.forEach((s) => {
    const card = document.createElement('div');
    card.className = 'stat-card' + (activeFilter === s.key ? ' is-active' : '');
    card.setAttribute('data-stage', s.key);

    const label = document.createElement('span');
    label.className = 'stat-label';
    label.textContent = s.label;

    const value = document.createElement('span');
    value.className = 'stat-value';
    value.textContent = String(counts[s.key]);

    card.appendChild(label);
    card.appendChild(value);
    el.stats.appendChild(card);
  });
  el.statsTotal.textContent = '共 ' + records.length + ' 条投递记录（各阶段合计 ' +
    STAGE_KEYS.reduce((sum, k) => sum + counts[k], 0) + ' 条）';
}

function renderFilters() {
  const records = getRecords();
  const counts = countByStage(records);
  const options = [{ key: FILTER_ALL, label: '全部', count: records.length }].concat(
    STAGES.map((s) => ({ key: s.key, label: s.label, count: counts[s.key] }))
  );
  el.filters.textContent = '';
  options.forEach((opt) => {
    const btn = document.createElement('button');
    btn.type = 'button';
    btn.className = 'filter-btn' + (activeFilter === opt.key ? ' is-active' : '');
    btn.setAttribute('data-filter', opt.key);
    btn.textContent = opt.label + '（' + opt.count + '）';
    btn.addEventListener('click', () => {
      activeFilter = opt.key;
      render();
    });
    el.filters.appendChild(btn);
  });
}

function buildRecordItem(record) {
  const li = document.createElement('li');
  li.className = 'record-item';
  li.setAttribute('data-stage', normalizeStage(record.stage));
  li.setAttribute('data-id', record.id);

  const top = document.createElement('div');
  top.className = 'record-top';

  const info = document.createElement('div');
  const company = document.createElement('h3');
  company.className = 'record-company';
  company.textContent = record.company || '（未填写公司）';
  const position = document.createElement('p');
  position.className = 'record-position';
  position.textContent = record.position || '（未填写岗位）';
  info.appendChild(company);
  info.appendChild(position);

  const badge = document.createElement('span');
  badge.className = 'stage-badge';
  badge.setAttribute('data-stage', normalizeStage(record.stage));
  badge.textContent = STAGE_LABEL[normalizeStage(record.stage)];

  top.appendChild(info);
  top.appendChild(badge);

  const meta = document.createElement('div');
  meta.className = 'record-meta';
  const dateSpan = document.createElement('span');
  dateSpan.textContent = '投递日期：' + (record.applyDate || '未填写');
  meta.appendChild(dateSpan);

  li.appendChild(top);
  li.appendChild(meta);

  if (record.note) {
    const note = document.createElement('p');
    note.className = 'record-note';
    note.textContent = record.note;
    li.appendChild(note);
  }

  const actions = document.createElement('div');
  actions.className = 'record-actions';

  const editBtn = document.createElement('button');
  editBtn.type = 'button';
  editBtn.className = 'btn btn-ghost btn-small';
  editBtn.textContent = '编辑';
  editBtn.addEventListener('click', () => { startEdit(record.id); });

  const delBtn = document.createElement('button');
  delBtn.type = 'button';
  delBtn.className = 'btn btn-danger btn-small';
  delBtn.textContent = '删除';
  delBtn.addEventListener('click', () => { requestDelete(record.id); });

  actions.appendChild(editBtn);
  actions.appendChild(delBtn);
  li.appendChild(actions);

  return li;
}

function renderList() {
  const records = getRecords();
  const visible = activeFilter === FILTER_ALL
    ? records
    : records.filter((r) => normalizeStage(r.stage) === activeFilter);

  el.list.textContent = '';
  visible.forEach((record) => {
    el.list.appendChild(buildRecordItem(record));
  });

  el.listCount.textContent = '显示 ' + visible.length + ' / 共 ' + records.length + ' 条';

  if (visible.length === 0) {
    el.empty.hidden = false;
    el.empty.textContent = records.length === 0
      ? '还没有投递记录，先在上方新增一条吧。'
      : '当前筛选阶段下暂无记录。';
  } else {
    el.empty.hidden = true;
    el.empty.textContent = '';
  }
}

function render() {
  renderStats();
  renderFilters();
  renderList();
}

function setFormError(message) {
  el.formError.textContent = message || '';
}

function resetForm() {
  editingId = null;
  el.company.value = '';
  el.position.value = '';
  el.date.value = todayISO();
  el.stage.value = 'pending';
  el.note.value = '';
  el.formTitle.textContent = '新增投递记录';
  el.submitBtn.textContent = '新增记录';
  el.cancelBtn.hidden = true;
  setFormError('');
}

function startEdit(id) {
  const record = getRecords().find((r) => r.id === id);
  if (!record) return;
  editingId = id;
  el.company.value = record.company;
  el.position.value = record.position;
  el.date.value = record.applyDate;
  el.stage.value = normalizeStage(record.stage);
  el.note.value = record.note;
  el.formTitle.textContent = '编辑投递记录';
  el.submitBtn.textContent = '保存修改';
  el.cancelBtn.hidden = false;
  setFormError('');
  el.company.focus();
}

async function persist(nextState) {
  await appStore.setState(nextState);
  const fresh = await appStore.getState();
  state = normalizeState(fresh);
}

async function handleSubmit(event) {
  event.preventDefault();
  if (saving) return;

  const company = el.company.value.trim();
  const position = el.position.value.trim();
  const applyDate = el.date.value;
  const stage = normalizeStage(el.stage.value);
  const note = el.note.value.trim();

  if (!company) { setFormError('请填写公司名称。'); return; }
  if (!position) { setFormError('请填写岗位名称。'); return; }
  if (!applyDate) { setFormError('请选择投递日期。'); return; }
  setFormError('');

  const targetId = editingId;
  const records = getRecords().slice();
  let nextRecords;

  if (targetId) {
    let found = false;
    nextRecords = records.map((r) => {
      if (r.id !== targetId) return r;
      found = true;
      return Object.assign({}, r, {
        company: company,
        position: position,
        applyDate: applyDate,
        stage: stage,
        note: note
      });
    });
    if (!found) {
      setFormError('未找到要编辑的记录，请刷新后重试。');
      return;
    }
  } else {
    const newRecord = {
      id: 'rec-' + Date.now() + '-' + Math.random().toString(36).slice(2, 8),
      company: company,
      position: position,
      applyDate: applyDate,
      stage: stage,
      note: note
    };
    nextRecords = records.concat([newRecord]);
  }

  const nextState = Object.assign({}, state, { records: nextRecords });
  saving = true;
  el.submitBtn.disabled = true;
  try {
    await persist(nextState);
    resetForm();
    render();
  } catch (err) {
    setFormError('保存失败，请重试。你的输入已保留。');
  } finally {
    saving = false;
    el.submitBtn.disabled = false;
  }
}

function openDialog(title, text, confirmLabel) {
  return new Promise((resolve) => {
    el.dialogTitle.textContent = title;
    el.dialogText.textContent = text;
    el.dialogConfirm.textContent = confirmLabel;
    el.dialogMask.hidden = false;

    function cleanup() {
      el.dialogMask.hidden = true;
      el.dialogConfirm.removeEventListener('click', onConfirm);
      el.dialogCancel.removeEventListener('click', onCancel);
      el.dialogMask.removeEventListener('click', onMaskClick);
      document.removeEventListener('keydown', onKeydown);
    }
    function onConfirm() { cleanup(); resolve(true); }
    function onCancel() { cleanup(); resolve(false); }
    function onMaskClick(e) { if (e.target === el.dialogMask) { cleanup(); resolve(false); } }
    function onKeydown(e) { if (e.key === 'Escape') { cleanup(); resolve(false); } }

    el.dialogConfirm.addEventListener('click', onConfirm);
    el.dialogCancel.addEventListener('click', onCancel);
    el.dialogMask.addEventListener('click', onMaskClick);
    document.addEventListener('keydown', onKeydown);
    el.dialogConfirm.focus();
  });
}

async function requestDelete(id) {
  const record = getRecords().find((r) => r.id === id);
  if (!record) return;
  const targetId = record.id;
  const targetName = (record.company || '该记录') + ' · ' + (record.position || '未填写岗位');

  const confirmed = await openDialog(
    '确认删除',
    '确定要删除「' + targetName + '」这条投递记录吗？删除后无法恢复。',
    '确认删除'
  );
  if (!confirmed) return;

  const nextRecords = getRecords().filter((r) => r.id !== targetId);
  const nextState = Object.assign({}, state, { records: nextRecords });
  try {
    await persist(nextState);
    if (editingId === targetId) resetForm();
    render();
  } catch (err) {
    setFormError('删除失败，请重试。');
  }
}

async function init() {
  const raw = await appStore.getState();
  state = normalizeState(raw);
  if (!Array.isArray(raw && raw.records)) {
    await persist(Object.assign({}, state, { records: [] }));
  }

  el.form.addEventListener('submit', handleSubmit);
  el.cancelBtn.addEventListener('click', () => { resetForm(); });

  resetForm();
  render();
}

await init();

