:root {
  --blue-900: #0b2545;
  --blue-700: #14427a;
  --blue-600: #1a5fb4;
  --blue-500: #2b7de9;
  --blue-100: #e3eefb;
  --blue-050: #f2f7fe;
  --white: #ffffff;
  --line: #d3e2f5;
  --text: #10233d;
  --text-soft: #5a7392;
  --danger: #c0392b;
  --danger-soft: #fdecea;
  --shadow: 0 6px 18px rgba(16, 66, 122, 0.10);
  --radius: 14px;
}

#app {
  min-height: 100vh;
  background: linear-gradient(180deg, var(--blue-050) 0%, #e8f1fc 55%, #dceafb 100%);
  color: var(--text);
  font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", "PingFang SC", "Hiragino Sans GB", "Microsoft YaHei", sans-serif;
  font-size: 15px;
  line-height: 1.55;
  -webkit-text-size-adjust: 100%;
}

#app *,
#app *::before,
#app *::after {
  box-sizing: border-box;
}

.app-shell {
  max-width: 720px;
  margin: 0 auto;
  padding: 18px 14px 48px;
  display: flex;
  flex-direction: column;
  gap: 16px;
}

.app-header {
  background: linear-gradient(135deg, var(--blue-700) 0%, var(--blue-500) 100%);
  color: var(--white);
  border-radius: var(--radius);
  padding: 20px 18px;
  box-shadow: var(--shadow);
}

.app-title {
  margin: 0;
  font-size: 21px;
  letter-spacing: 0.5px;
}

.app-subtitle {
  margin: 6px 0 0;
  font-size: 13px;
  color: #dbe9fb;
}

.stats {
  background: var(--white);
  border: 1px solid var(--line);
  border-radius: var(--radius);
  padding: 14px;
  box-shadow: var(--shadow);
}

.stats-grid {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 10px;
}

.stat-card {
  background: var(--blue-050);
  border: 1px solid var(--line);
  border-radius: 12px;
  padding: 10px 12px;
  display: flex;
  flex-direction: column;
  gap: 2px;
}

.stat-card.is-active {
  border-color: var(--blue-500);
  background: var(--blue-100);
}

.stat-label {
  font-size: 12.5px;
  color: var(--text-soft);
}

.stat-value {
  font-size: 20px;
  font-weight: 700;
  color: var(--blue-700);
}

.stats-total {
  margin: 12px 0 0;
  font-size: 13px;
  color: var(--text-soft);
  border-top: 1px dashed var(--line);
  padding-top: 10px;
}

.panel {
  background: var(--white);
  border: 1px solid var(--line);
  border-radius: var(--radius);
  padding: 16px 14px;
  box-shadow: var(--shadow);
}

.panel-title {
  margin: 0 0 12px;
  font-size: 16px;
  color: var(--blue-900);
}

.record-form {
  display: grid;
  grid-template-columns: 1fr;
  gap: 12px;
}

.field {
  display: flex;
  flex-direction: column;
  gap: 6px;
}

.field label {
  font-size: 13px;
  font-weight: 600;
  color: var(--blue-700);
}

.field input,
.field select,
.field textarea {
  width: 100%;
  font: inherit;
  color: var(--text);
  background: var(--blue-050);
  border: 1px solid var(--line);
  border-radius: 10px;
  padding: 10px 11px;
  outline: none;
  transition: border-color 0.15s ease, box-shadow 0.15s ease, background 0.15s ease;
}

.field textarea {
  resize: vertical;
  min-height: 72px;
}

.field input:focus,
.field select:focus,
.field textarea:focus {
  background: var(--white);
  border-color: var(--blue-500);
  box-shadow: 0 0 0 3px rgba(43, 125, 233, 0.18);
}

.field input::placeholder,
.field textarea::placeholder {
  color: #93a9c4;
}

.form-error {
  margin: 0;
  min-height: 18px;
  font-size: 13px;
  color: var(--danger);
}

.form-actions {
  display: flex;
  flex-wrap: wrap;
  gap: 10px;
}

.btn {
  font: inherit;
  font-weight: 600;
  border-radius: 10px;
  border: 1px solid transparent;
  padding: 10px 16px;
  cursor: pointer;
  transition: background 0.15s ease, color 0.15s ease, border-color 0.15s ease;
}

.btn-primary {
  background: var(--blue-600);
  color: var(--white);
}

.btn-primary:hover {
  background: var(--blue-700);
}

.btn-ghost {
  background: var(--white);
  color: var(--blue-700);
  border-color: var(--line);
}

.btn-ghost:hover {
  background: var(--blue-050);
}

.btn-danger {
  background: var(--danger);
  color: var(--white);
}

.btn-danger:hover {
  background: #a5311f;
}

.btn-small {
  padding: 6px 12px;
  font-size: 13px;
  border-radius: 8px;
}

.list-head {
  display: flex;
  align-items: baseline;
  justify-content: space-between;
  gap: 10px;
}

.list-count {
  font-size: 12.5px;
  color: var(--text-soft);
}

.filters {
  display: flex;
  flex-wrap: wrap;
  gap: 8px;
  margin: 4px 0 14px;
}

.filter-btn {
  font: inherit;
  font-size: 13px;
  padding: 7px 13px;
  border-radius: 999px;
  border: 1px solid var(--line);
  background: var(--blue-050);
  color: var(--blue-700);
  cursor: pointer;
  transition: background 0.15s ease, color 0.15s ease, border-color 0.15s ease;
}

.filter-btn:hover {
  background: var(--blue-100);
}

.filter-btn.is-active {
  background: var(--blue-600);
  border-color: var(--blue-600);
  color: var(--white);
}

.record-list {
  list-style: none;
  margin: 0;
  padding: 0;
  display: flex;
  flex-direction: column;
  gap: 10px;
}

.record-item {
  border: 1px solid var(--line);
  border-left: 4px solid var(--blue-500);
  border-radius: 12px;
  background: var(--blue-050);
  padding: 12px;
  display: flex;
  flex-direction: column;
  gap: 8px;
}

.record-item[data-stage="pending"] { border-left-color: #7f9dc0; }
.record-item[data-stage="applied"] { border-left-color: var(--blue-500); }
.record-item[data-stage="interview"] { border-left-color: #f0a020; }
.record-item[data-stage="closed"] { border-left-color: #8d9aa8; }

.record-top {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  gap: 10px;
}

.record-company {
  margin: 0;
  font-size: 15.5px;
  color: var(--blue-900);
  word-break: break-word;
}

.record-position {
  margin: 2px 0 0;
  font-size: 13.5px;
  color: var(--text-soft);
  word-break: break-word;
}

.stage-badge {
  flex: 0 0 auto;
  font-size: 12px;
  font-weight: 600;
  padding: 4px 10px;
  border-radius: 999px;
  background: var(--blue-100);
  color: var(--blue-700);
  white-space: nowrap;
}

.stage-badge[data-stage="interview"] {
  background: #fdf1dc;
  color: #9a6206;
}

.stage-badge[data-stage="closed"] {
  background: #eceff3;
  color: #5c6b7a;
}

.record-meta {
  display: flex;
  flex-wrap: wrap;
  gap: 4px 14px;
  font-size: 12.5px;
  color: var(--text-soft);
}

.record-note {
  margin: 0;
  font-size: 13px;
  color: var(--text);
  background: var(--white);
  border: 1px dashed var(--line);
  border-radius: 8px;
  padding: 8px 10px;
  white-space: pre-wrap;
  word-break: break-word;
}

.record-actions {
  display: flex;
  gap: 8px;
  justify-content: flex-end;
}

.empty-hint {
  margin: 6px 0 0;
  padding: 18px 12px;
  text-align: center;
  font-size: 13.5px;
  color: var(--text-soft);
  background: var(--blue-050);
  border: 1px dashed var(--line);
  border-radius: 12px;
}

.dialog-mask {
  position: fixed;
  inset: 0;
  background: rgba(11, 37, 69, 0.45);
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 20px;
  z-index: 50;
}

.dialog-mask[hidden] {
  display: none;
}

.dialog {
  width: 100%;
  max-width: 360px;
  background: var(--white);
  border-radius: var(--radius);
  padding: 18px 16px;
  box-shadow: 0 18px 40px rgba(11, 37, 69, 0.28);
}

.dialog-title {
  margin: 0 0 8px;
  font-size: 16px;
  color: var(--blue-900);
}

.dialog-text {
  margin: 0 0 16px;
  font-size: 13.5px;
  color: var(--text-soft);
  word-break: break-word;
}

.dialog-actions {
  display: flex;
  justify-content: flex-end;
  gap: 10px;
}

@media (min-width: 560px) {
  .app-shell {
    padding: 26px 20px 60px;
  }
  .stats-grid {
    grid-template-columns: repeat(4, minmax(0, 1fr));
  }
  .record-form {
    grid-template-columns: 1fr 1fr;
  }
  .field-wide,
  .form-error,
  .form-actions {
    grid-column: 1 / -1;
  }
}
